import os
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _normalize_currency_amount(value: Any) -> Optional[float]:
    if value is None:
        return None
    try:
        if hasattr(value, "value"):
            value = value.value
        return float(value)
    except Exception:
        try:
            return float(str(value).replace(",", "").strip())
        except Exception:
            return None


def _get_field_content(field: Any) -> Any:
    if field is None:
        return None
    for attr in ("content", "value", "value_string", "value_date", "value_number"):
        if hasattr(field, attr):
            v = getattr(field, attr)
            if v is not None:
                return v
    return field


def extract_invoice_fields(file_path: str) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    with open(file_path, "rb") as f:
        poller = client.begin_analyze_document(
            model_id="prebuilt-invoice",
            body=f,
        )
    result = poller.result()

    vendor = None
    date = None
    total = None
    line_items: List[Dict[str, Any]] = []

    documents = getattr(result, "documents", None) or []
    if documents:
        doc = documents[0]
        fields = getattr(doc, "fields", {}) or {}

        vendor_field = fields.get("VendorName")
        if vendor_field:
            vendor = _get_field_content(vendor_field)

        date_field = fields.get("InvoiceDate")
        if date_field:
            date = _get_field_content(date_field)

        total_field = fields.get("InvoiceTotal")
        if total_field:
            total = _normalize_currency_amount(_get_field_content(total_field))

        items_field = fields.get("Items")
        if items_field and getattr(items_field, "value_array", None):
            for item in items_field.value_array:
                item_fields = getattr(item, "value_object", {}) or {}
                line_items.append(
                    {
                        "description": _get_field_content(item_fields.get("Description")),
                        "quantity": _normalize_currency_amount(_get_field_content(item_fields.get("Quantity"))),
                        "unit_price": _normalize_currency_amount(_get_field_content(item_fields.get("UnitPrice"))),
                        "amount": _normalize_currency_amount(_get_field_content(item_fields.get("Amount"))),
                    }
                )

    return {
        "vendor": vendor,
        "date": date,
        "total": total,
        "line_items": line_items,
    }
